SELECT ?z ?class ?label WHERE {
  ?z a ?class .
  ?z rdfs:label ?label .
  FILTER (contains(LCASE(?label),"zn") || contains(LCASE(?label),"zone") || contains(LCASE(?label),"z6"))
} LIMIT 100

SELECT ?sensor ?label ?tid WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  OPTIONAL { ?sensor rdfs:label ?label }
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tid }
} LIMIT 100

SELECT ?z ?class WHERE {
  ?z a brick:HVACZone .
  ?z rdfs:label ?l .
  FILTER (contains(LCASE(?l),"datacenter"))
}

SELECT ?z ?class ?l WHERE {
  ?z a ?class .
  ?z rdfs:label ?l .
  FILTER (contains(?l,"top-ZN_6") || contains(?l,"Top_ZN_6") || contains(?l,"DataCenter-top") || contains(?l,"DataCenter_top"))
}

SELECT ?z ?l WHERE {
  ?z a brick:HVAC_Zone .
